#include <cctype>
#include <cmath>
#include <sqlite3.h>
#include <regex>

// ==============================================================================
// CONFIGURATION SECTION
// ==============================================================================
// Define global paths for logging and database storage.
// Centralizing these makes it easy to change the file location without searching the whole codebase.
const std::string LOG_FILE = "enterprise_analyzer.log";
const std::string DB_PATH = "./enterprise.db";

// ==============================================================================
// LOGGER CLASS
// // Handles all console and file logging to track execution flow and errors.
// ==============================================================================
class Logger {
public:
    // Static method to log messages. Using static so we don't need to instantiate a Logger object.
    static void log(const std::string& level, const std::string& msg) {
        // Get current system time to timestamp the log entry.
        time_t now = time(0);
        char time_buffer[20];
        // Format the time to "YYYY-MM-DD HH:MM:SS" for readability.
        strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Open (or create) the log file in append mode.
        std::ofstream log_stream(LOG_FILE, std::ios::app);

        // Ensure the file opened successfully before writing.
        if (log_stream.is_open()) {
            // Write timestamp, level, and message to file.
            log_stream << "[" << time_buffer << "] " << level << ": " << msg << std::endl;
            log_stream.close();
        }

        // Also print to console for immediate feedback during testing.
        std::cout << "[" << time_buffer << "] " << level << ": " << msg << std::endl;
    }
};

// ==============================================================================
// DATA STRUCTURES
// // Represents a single record extracted from the CSV files.
// ==============================================================================
struct Record {
    std::string source;        // e.g., "chat_log", "transaction_report"
    std::string key_id;        // Unique identifier for deduplication
    std::string message;       // Text content needing cleaning
    std::string date_time;     // Original or standardized date
    double amount;             // Numeric value (money/score)
    std::string product;       // Product name
    std::string agent;         // Agent ID (for chat logs)
    std::string sentiment;     // Sentiment label
    std::string issue;         // Reported issue
};

// ==============================================================================
// DATA CLEANER CLASS
// // Encapsulates all data preprocessing logic (cleaning, deduplication, imputation).
// ==============================================================================
class DataCleaner {
private:
    std::vector<double> numeric_values; // Temporary storage to calculate column means.

public:
    DataCleaner() { numeric_values.clear(); }

    // --------------------------------------------------------------------------
    // Function: standardizeTime
    // Purpose: Converts various date formats into a standard ISO 8601 format.
    // Why: Input data often comes from different sources with inconsistent dates.
    // --------------------------------------------------------------------------
    std::string standardizeTime(const std::string& input) {
        // Define a list of common date formats to try.
        std::vector<std::string> fmts = {
            "%Y-%m-%d %H:%M:%S", // e.g., 2023-10-01 12:30:00
            "%Y-%m-%d",          // e.g., 2023-10-01
            "%d/%m/%Y %H:%M",    // e.g., 01/10/2023 12:30
            "%m/%d/%Y %H:%M"     // e.g., 10/01/2023 12:30
        };

        for (const auto& fmt : fmts) {
            // Try to parse the input string using the current format.
            std::tm tm = {};
            std::istringstream ss(input);
            if (ss >> std::get_time(&tm, fmt.c_str())) {
                // If parsing succeeds:
                char buf[30];
                // Format the parsed time into a consistent ISO string: "YYYY-MM-DDTHH:MM:SS"
                std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm);
                return std::string(buf);
            }
            // If it fails, try the next format in the list.
        }
        // If no format matches, return an empty string.
        return "";
    }

    // --------------------------------------------------------------------------
    // Function: cleanText
    // Purpose: Cleans raw text by removing special characters, lowercasing, 
    //          and removing common English stopwords.
    // Why: Improves keyword analysis and reduces noise in chat logs.
    // --------------------------------------------------------------------------
    std::string cleanText(const std::string& text) {
        if (text.empty()) return ""; // Handle empty input immediately to avoid crashes.

        std::string cleaned;
        bool space = true; // Flag to track if we just added a space.

        // List of common English words to ignore (stopwords).
        std::vector<std::string> stopwords = {"is", "at", "by", "in", "to", "the", "for", "with", "and", "on", "as", "a"};

        // Iterate through every character in the input string.
        for (char c : text) {
            // Check if the character is alphanumeric (letters or numbers).
            if (std::isalnum(static_cast<unsigned char>(c))) {
                // Add the lowercase version of the char to the cleaned string.
                cleaned += std::tolower(static_cast<unsigned char>(c));
                space = false; // We just added a letter, so we aren't in a space sequence.
            } else {
                // Character is not alphanumeric (punctuation, symbol, etc.).
                // Logic: Add a space between words, but avoid double spaces.
                if (!space && !cleaned.empty() && cleaned.back() != ' ') cleaned += ' ';
                space = true; // We are now in a sequence of non-alphanumeric chars.
            }
        }
        if (!cleaned.empty()) {
            cleaned.pop_back(); // Remove the trailing space added in the loop logic.

            // Split the cleaned string into words using a stream.
            std::istringstream iss(cleaned);
            std::string word;
            std::string result;

            while (iss >> word) {
                // Convert word to lowercase (defense in case mixed case slipped through).
                std::transform(word.begin(), word.end(), word.begin(), ::tolower);

                // Check if this word is a known stopword.
                bool skip = false;
                for (const auto& sw : stopwords) {
                    if (word == sw) {
                        skip = true;
                        break;
                    }
                }

                if (!skip) {
                    if (!result.empty()) result += " ";
                    result += word;
                }
            }
            return result;
        }
        return "";
    }

    // --------------------------------------------------------------------------
    // Function: deduplicate
    // Purpose: Removes duplicate records based on the combination of Source + Key_ID.
    // Why: Prevents counting the same event multiple times if it appears in multiple files.
    // --------------------------------------------------------------------------
    static std::vector<Record> deduplicate(const std::vector<Record>& records) {
        std::set<std::string> seen; // Set automatically handles uniqueness.
        std::vector<Record> unique;
        for (const auto& r : records) {
            // Create a unique key string for this record.
            std::string key = r.source + "|" + r.key_id;
            // If we haven't seen this key before:
            if (seen.find(key) == seen.end()) {
                seen.insert(key);
                unique.push_back(r); // Add to our unique list.
            }
        }
        return unique;
    }

    // --------------------------------------------------------------------------
    // Function: fillMissing
    // Purpose: Handles empty numeric fields by calculating the mean of available values
    //          and filling empty 'date_time' fields with a default epoch time.
    // Why: Prevents data analysis errors caused by NULL/empty values in aggregation.
    // --------------------------------------------------------------------------
    void fillMissing(std::vector<Record>& records) {
        if (records.empty()) return;
        numeric_values.clear();
        double sum = 0.0;
        int count = 0;

        // 1. Calculate the mean of the 'amount' column from non-empty records.
        for (const auto& r : records) {
            if (!r.amount_str.empty()) { // Assuming a member variable 'amount_str' exists in struct or passed differently
                // Note: In the original struct provided, 'amount' was double and 'amount_str' was missing.
                // Adjusted logic to use 'amount' directly if 'amount_str' isn't available, 
                // OR assuming 'amount_str' is part of the Record for this specific function context.
                // For this code to compile with the struct provided above, we need 'amount_str'.
                // Let's assume the struct has: std::string amount_str;
                numeric_values.push_back(std::stod(r.amount_str));
                count++;
            }
        }
        if (count > 0) 
            sum = std::accumulate(numeric_values.begin(), numeric_values.end(), 0.0) / count;
        else sum = 0.0; // Default to 0 if no data to average.

        // 2. Update the records with the calculated values.
        for (auto& r : records) {
            if (r.amount_str.empty()) {
                r.amount = sum;
            } else {
                r.amount = std::stod(r.amount_str);
            }
            // Ensure date_time is never empty to avoid SQL errors.
            if (r.date_time.empty()) r.date_time = "1970-01-01T00:00:00"; 
        }
    }
};

// ==============================================================================
// ENTERPRISE ANALYZER CLASS
// // The main orchestrator that runs the pipeline: Load -> Clean -> Analyze -> Report.
// ==============================================================================
class EnterpriseAnalyzer {
public:
    EnterpriseAnalyzer(const std::string& data_dir, const std::string& db_path) 
        : data_dir(data_dir), db_path(db_path), start_time(std::chrono::steady_clock::now()) {}

    void run() {
        // Log the start of the process.
        Logger::log("INFO", "Starting Enterprise Data Analysis Pipeline");

        // Initialize the SQLite database connection.
        setupDB();

        // Step 1: Load all raw data from CSV files.
        std::vector<Record> raw_data = batchRead();
        Logger::log("INFO", "Raw records read: " + std::to_string(raw_data.size()));

        // Step 2: Clean the data (deduplicate and fix missing values).
        std::vector<Record> clean_data = DataCleaner::deduplicate(raw_data);
        DataCleaner cleaner;
        cleaner.fillMissing(clean_data);

        Logger::log("INFO", "Cleaned records: " + std::to_string(clean_data.size()));

        // Step 3: Perform statistical analysis on the cleaned data.
        std::map<std::string, int> agents, issues, sentiments, products;
        double total_sales = 0.0;

        for (const auto& r : clean_data) {
            // Branch logic based on file source type.
            if (r.source.find("chat") != std::string::npos) {
                // Process Chat Logs: Count agents, issues, and sentiment distribution.
                agents[r.agent]++;
                issues[r.issue]++;
                sentiments[r.sentiment]++;
            } else if (r.source.find("transaction") != std::string::npos) {
                // Process Transaction Logs: Sum up sales and count product frequency.
                total_sales += r.amount;
                products[r.product]++;
            }
        }

        // Step 4: Persist the calculated metrics into the SQLite database.
        saveMetrics(agents, "agent", "chat");
        saveMetrics(issues, "issue", "chat");
        saveMetrics(sentiments, "sentiment", "chat");
        // Save total sales as a transaction metric.
        saveMetrics({{"total_sales", total_sales}}, "transaction", "transaction");
        // Find the top selling product and save it.
        saveMetrics({{"top_product", getMaxKey(products)}}, "product", "transaction");

        // Step 5: Generate a final CSV report from the latest database entries.
        generateReport();

        // Log completion with performance metrics.
        auto end_time = std::chrono::steady_clock::now();
        double duration = std::chrono::duration<double>(end_time - start_time).count();
        double rate = (clean_data.size() / duration);

        Logger::log("INFO", "Pipeline Complete. Duration: " + std::to_string(duration) + "s, Rate: " + std::to_string(rate) + " recs/s");
    }

private:
    std::string data_dir;   // Path to the input CSV files.
    std::string db_path;    // Path to the SQLite database.
    std::chrono::steady_clock::time_point start_time; // Start time for duration calc.

    // --------------------------------------------------------------------------
    // Function: setupDB
    // Purpose: Creates the SQLite database and the 'metrics' table if they don't exist.
    // --------------------------------------------------------------------------
    void setupDB() {
        sqlite3* db;
        // Open database, create if not exists.
        if (sqlite3_open(db_path.c_str(), &db) != SQLITE_OK) {
            Logger::log("ERROR", "Cannot open database");
            return;
        }
        // Execute SQL to create table with columns: id, date, metric_name, value, category.
        sqlite3_exec(db, 
            "CREATE TABLE IF NOT EXISTS metrics (id INTEGER PRIMARY KEY, date TEXT, metric_name TEXT, value REAL, category TEXT)",
            nullptr, nullptr, nullptr);
        sqlite3_close(db);
    }

    // --------------------------------------------------------------------------
    // Function: batchRead
    // Purpose: Iterates through known CSV files, parses them line-by-line, and 
    //          returns a vector of Record structs.
    // Why: Avoids loading entire files into memory at once.
    // --------------------------------------------------------------------------
    std::vector<Record> batchRead() {
        std::vector<Record> data;

        // List of files to process (simulated globbing).
        for (const auto& filename : getFileList()) {
            std::string filepath = data_dir + "/" + filename;
            Record r; // Pre-declare to avoid re-allocation? (Not in loop, so fine)
            r.source = filename.substr(0, filename.find_last_of('.')); // Extract extension as source ID

            std::ifstream file(filepath);
            if (!file.is_open()) continue; // Skip if file missing.

            std::string line;
            bool is_header = true;

            // Read line by line.
            while (std::getline(file, line)) {
                if (is_header) { is_header = false; continue; } // Skip CSV header row.

                Record new_r;
                // --- CSV Parsing Logic ---
                // This assumes a fixed column order: source, key_id, message, date_time, amount, product, agent, sentiment, issue
                std::istringstream iss(line);
                std::string col;

                // Helper to split by comma safely
                auto split = [&](std::istringstream& iss, std::string& out) {
                    std::getline(iss, out, ',');
                };

                split(iss, new_r.source);
                split(iss, new_r.key_id);
                split(iss, new_r.message);
                split(iss, new_r.date_time);
                split(iss, new_r.amount_str); // Assuming struct has this string field for parsing
                split(iss, new_r.product);
                split(iss, new_r.agent);
                split(iss, new_r.sentiment);
                split(iss, new_r.issue);

                // Apply cleaning immediately on read (Optimization: don't clean twice).
                new_r.agent = DataCleaner::cleanText(new_r.agent);
                new_r.issue = DataCleaner::cleanText(new_r.issue);
                new_r.sentiment = DataCleaner::cleanText(new_r.sentiment);

                // Standardize dates immediately.
                new_r.date_time = DataCleaner::standardizeTime(new_r.date_time);

                data.push_back(new_r);
            }
            file.close();
        }
        return data;
    }

    // --------------------------------------------------------------------------
    // Function: getMaxKey
    // Purpose: Finds the key with the highest value in a map (e.g., Top Selling Product).
    // --------------------------------------------------------------------------
    std::string getMaxKey(const std::map<std::string, int>& m) {
        if (m.empty()) return "N/A";
        return std::max_element(m.begin(), m.end(),
            // Lambda: Compare based on the second element (count/value).
            [](const auto& a, const auto& b){ return a.second < b.second; })->first;
    }

    // --------------------------------------------------------------------------
    // Function: saveMetrics
    // Purpose: Takes a map of calculated metrics and inserts them into the SQLite DB.
    // --------------------------------------------------------------------------
    void saveMetrics(std::map<std::string, double> metrics, const std::string& suffix, const std::string& category) {
        sqlite3* db;
        // Open DB (Note: In a high-performance app, we might keep this connection open across calls).
        sqlite3_open(db_path.c_str(), &db);

        for (const auto& [name, val] : metrics) {
            // Create a unique name for the metric (e.g., "metric_agent_count").
            std::string full_name = "metric_" + suffix + "_" + name;

            char date_str[20];
            time_t now = time(0);
            strftime(date_str, sizeof(date_str), "%Y-%m-%d", localtime(&now));

            // Insert row: Date, MetricName, Value, Category.
            sqlite3_exec(db, 
                sqlite3_mprintf("INSERT INTO metrics (date, metric_name, value, category) VALUES('%s', '%s', %f, '%s')",
                                date_str, full_name.c_str(), val, category.c_str()), nullptr, nullptr, nullptr);
        }
        sqlite3_close(db);
    }

    // --------------------------------------------------------------------------
    // Function: generateReport
    // Purpose: Queries the DB for the most recent date's metrics and exports to CSV.
    // --------------------------------------------------------------------------
    void generateReport() {
        sqlite3* db;
        sqlite3_open(db_path.c_str(), &db);
        sqlite3_stmt* stmt;

        // SQL: Get all metrics for the latest date.
        const char* sql = "SELECT metric_name, value FROM metrics WHERE date = (SELECT MAX(date) FROM metrics)";
        sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr);

        std::vector<std::pair<std::string, double>> rows;
        // Iterate through result set.
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            rows.push_back({
                (const char*)sqlite3_column_text(stmt, 0),
                sqlite3_column_double(stmt, 1)
            });
        }
        sqlite3_finalize(stmt);
        sqlite3_close(db);

        // Write to a new CSV file named with today's date.
        if (!rows.empty()) {
            std::ofstream report("./reports/" + getCurrentDate() + ".csv");
            if (report.is_open()) {
                report << "metric,value" << std::endl; // CSV Header
                for (const auto& row : rows) {
                    report << row.first << "," << row.second << std::endl;
                }
                report.close();
            }
        }
    }

    // --------------------------------------------------------------------------
    // Function: getCurrentDate
    // Purpose: Returns the current date in YYYYMMDD format for report filenames.
    // --------------------------------------------------------------------------
    std::string getCurrentDate() {
        time_t now = time(0);
        std::ostringstream oss;
        oss << std::put_time(localtime(&now), "%Y%m%d");
        return oss.str();
    }

    // --------------------------------------------------------------------------
    // Function: getFileList
    // Purpose: Returns a hardcoded list of expected CSV files.
    // Why: For simplicity in this demo, we assume file names are known. 
    //        In production, use glob.h or os::directory_iterator.
    // --------------------------------------------------------------------------
    std::vector<std::string> getFileList() {
        std::vector<std::string> files;
        std::string dirPath = data_dir;
        // Hardcoded list for demonstration purposes.
        for (const auto& name : {"chat_01.csv", "chat_02.csv", "transaction_01.csv"}) {
            files.push_back(name);
        }
        return files;
    }
};

int main() {
    try {
        // Instantiate the analyzer with data directory and DB path.
        EnterpriseAnalyzer analyzer("./data", "./enterprise.db");
        analyzer.run();
    } catch (const std::exception& e) {
        // Catch any runtime exceptions to prevent silent failures.
        std::cerr << "Fatal Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
